create table if not exists public.education_audience_stages (
  stage_key text primary key,
  audience_group text not null check (audience_group in ('school','higher_education')),
  title text not null,
  subtitle text,
  min_grade smallint,
  max_grade smallint,
  display_order smallint not null,
  school_stage boolean not null default false,
  transition_stage boolean not null default false,
  created_at timestamptz not null default now(),
  constraint education_stage_grade_range_chk check ((audience_group='school' and min_grade between 1 and 12 and max_grade between 1 and 12 and min_grade<=max_grade) or (audience_group='higher_education' and min_grade is null and max_grade is null))
);
insert into public.education_audience_stages(stage_key,audience_group,title,subtitle,min_grade,max_grade,display_order,school_stage,transition_stage) values
('school_1_6','school','Grades 1–6','Elementary foundations',1,6,10,true,false),
('school_7_8','school','Grades 7–8','Intermediate exploration',7,8,20,true,false),
('school_9_10','school','Grades 9–10','Secondary skills and pathways',9,10,30,true,true),
('school_11_12','school','Grades 11–12','Senior secondary and transition',11,12,40,true,true),
('college_tvet','higher_education','College / TVET','Practical and technical education',null,null,50,false,true),
('university','higher_education','University','Higher education and career launch',null,null,60,false,true)
on conflict(stage_key) do update set title=excluded.title,subtitle=excluded.subtitle,min_grade=excluded.min_grade,max_grade=excluded.max_grade,display_order=excluded.display_order,school_stage=excluded.school_stage,transition_stage=excluded.transition_stage;

