alter table public.profiles add column if not exists education_stage_key text references public.education_audience_stages(stage_key) on update cascade on delete set null;
alter table public.profiles add column if not exists grade_level smallint check(grade_level between 1 and 12);
alter table public.profiles add column if not exists institution_name text;
alter table public.profiles add column if not exists learner_safety_status text not null default 'not_applicable' check(learner_safety_status in ('not_applicable','guardian_required','guardian_verified','adult_self_attested'));
alter table public.profiles add column if not exists education_onboarding_completed boolean not null default false;
create index if not exists profiles_education_stage_idx on public.profiles(education_stage_key) where role='student';
create index if not exists profiles_grade_level_idx on public.profiles(grade_level) where grade_level is not null;

create or replace function private.sync_profile_education_stage() returns trigger language plpgsql set search_path to '' as $function$
begin
 if new.role<>'student' then new.education_stage_key:=null;new.grade_level:=null;new.learner_safety_status:='not_applicable';new.education_onboarding_completed:=false;return new;end if;
 if new.grade_level is not null then new.education_stage_key:=case when new.grade_level between 1 and 6 then 'school_1_6' when new.grade_level between 7 and 8 then 'school_7_8' when new.grade_level between 9 and 10 then 'school_9_10' when new.grade_level between 11 and 12 then 'school_11_12' else new.education_stage_key end;end if;
 if new.education_stage_key in ('college_tvet','university') then new.grade_level:=null;new.learner_safety_status:='not_applicable';new.education_onboarding_completed:=true;
 elsif new.education_stage_key in ('school_1_6','school_7_8','school_9_10','school_11_12') then if new.learner_safety_status='not_applicable' then new.learner_safety_status:='guardian_required';end if;new.education_onboarding_completed:=new.grade_level is not null;
 else new.education_onboarding_completed:=false;end if;return new;
end;$function$;
drop trigger if exists trg_sync_profile_education_stage on public.profiles;
create trigger trg_sync_profile_education_stage before insert or update of role,grade_level,education_stage_key,learner_safety_status on public.profiles for each row execute function private.sync_profile_education_stage();

