alter table public.education_audience_stages enable row level security;alter table public.sector_partner_types enable row level security;alter table public.audience_feature_matrix enable row level security;alter table public.audience_opportunity_rules enable row level security;alter table public.platform_audience_sections enable row level security;alter table public.platform_audience_subsections enable row level security;
create policy education_stages_read on public.education_audience_stages for select to anon,authenticated using(true);create policy partner_types_read on public.sector_partner_types for select to anon,authenticated using(true);create policy audience_feature_matrix_read on public.audience_feature_matrix for select to authenticated using(true);create policy audience_opportunity_rules_read on public.audience_opportunity_rules for select to authenticated using(true);create policy audience_sections_read on public.platform_audience_sections for select to anon,authenticated using(active);create policy audience_subsections_read on public.platform_audience_subsections for select to anon,authenticated using(active);
create policy mela_gate_platform_live on public.education_audience_stages as restrictive for all to anon,authenticated using(public.platform_feature_available('platform_live')) with check(public.platform_feature_available('platform_live'));create policy mela_gate_platform_live on public.sector_partner_types as restrictive for all to anon,authenticated using(public.platform_feature_available('platform_live')) with check(public.platform_feature_available('platform_live'));create policy mela_gate_platform_live on public.audience_feature_matrix as restrictive for all to anon,authenticated using(public.platform_feature_available('platform_live')) with check(public.platform_feature_available('platform_live'));create policy mela_gate_platform_live on public.audience_opportunity_rules as restrictive for all to anon,authenticated using(public.platform_feature_available('platform_live')) with check(public.platform_feature_available('platform_live'));create policy mela_gate_platform_live on public.platform_audience_sections as restrictive for all to anon,authenticated using(public.platform_feature_available('platform_live')) with check(public.platform_feature_available('platform_live'));create policy mela_gate_platform_live on public.platform_audience_subsections as restrictive for all to anon,authenticated using(public.platform_feature_available('platform_live')) with check(public.platform_feature_available('platform_live'));
