create or replace function public.set_my_education_context(p_stage_key text,p_grade_level smallint default null,p_institution_name text default null) returns public.profiles language plpgsql security invoker set search_path to '' as $function$ declare v_uid uuid:=(select auth.uid());v_stage public.education_audience_stages%rowtype;v public.profiles%rowtype;begin if v_uid is null then raise exception 'authentication required';end if;select * into v_stage from public.education_audience_stages where stage_key=p_stage_key;if not found then raise exception 'unsupported education stage';end if;if v_stage.audience_group='school' then if p_grade_level is null or p_grade_level<v_stage.min_grade or p_grade_level>v_stage.max_grade then raise exception 'grade level does not match selected stage';end if;else p_grade_level:=null;end if;update public.profiles set education_stage_key=p_stage_key,grade_level=p_grade_level,institution_name=nullif(trim(coalesce(p_institution_name,'')),''),school_name=case when v_stage.audience_group='school' then coalesce(nullif(trim(coalesce(p_institution_name,'')),''),school_name) else school_name end,university=case when p_stage_key='university' then coalesce(nullif(trim(coalesce(p_institution_name,'')),''),university) else university end,updated_at=now() where id=v_uid and role='student' returning * into v;if not found then raise exception 'student profile required';end if;return v;end;$function$;
create or replace function public.my_audience_feature_access(p_feature_key text) returns text language sql stable security invoker set search_path to '' as $function$ select case when not public.platform_feature_available(p_feature_key) then 'globally_disabled' when p.role<>'student' then 'enabled' when p.education_stage_key is null then 'onboarding_required' else coalesce((select m.access_mode from public.audience_feature_matrix m where m.stage_key=p.education_stage_key and m.feature_key=p_feature_key),'hidden') end from public.profiles p where p.id=(select auth.uid()); $function$;
create or replace function public.get_my_audience_context() returns jsonb language sql stable security invoker set search_path to '' as $function$ with me as(select p.*,s.audience_group,s.title stage_title,s.subtitle stage_subtitle,s.school_stage from public.profiles p left join public.education_audience_stages s on s.stage_key=p.education_stage_key where p.id=(select auth.uid())),features as(select coalesce(jsonb_object_agg(m.feature_key,m.access_mode),'{}'::jsonb) j from me join public.audience_feature_matrix m on m.stage_key=me.education_stage_key),sections as(select coalesce(jsonb_agg(jsonb_build_object('section_key',x.section_key,'title',x.title,'description',x.description,'display_order',x.display_order,'subsections',x.subsections) order by x.display_order),'[]'::jsonb) j from(select s.section_key,s.title,s.description,s.display_order,coalesce(jsonb_agg(jsonb_build_object('subsection_key',ss.subsection_key,'title',ss.title,'description',ss.description,'route_key',ss.route_key,'display_order',ss.display_order) order by ss.display_order) filter(where ss.subsection_key is not null),'[]'::jsonb) subsections from me join public.platform_audience_sections s on s.audience_group=case when me.audience_group='school' then 'school' when me.audience_group='higher_education' then 'higher_education' else 'school' end and s.active left join public.platform_audience_subsections ss on ss.section_key=s.section_key and ss.active and me.education_stage_key=any(ss.target_stages) group by s.section_key,s.title,s.description,s.display_order having count(ss.subsection_key)>0)x) select jsonb_build_object('role',me.role,'stage_key',me.education_stage_key,'stage_title',me.stage_title,'stage_subtitle',me.stage_subtitle,'grade_level',me.grade_level,'institution_name',coalesce(me.institution_name,me.school_name,me.university),'safety_status',me.learner_safety_status,'onboarding_completed',me.education_onboarding_completed,'features',(select j from features),'sections',(select j from sections)) from me; $function$;
grant execute on function public.set_my_education_context(text,smallint,text),public.my_audience_feature_access(text),public.get_my_audience_context() to authenticated;
;
